const repeatMistakesBecomeExperience = H.trigger('repeatMistakesBecomeExperience')
  .on(H.when.step(drafts, 'factCheck', { if: event => typeof event.output?.repeatMistake === 'string' }))
  .record(factCheckLessons, event =>
